func _spine_event_class(is_dot, did_crit):
				if is_dot:
								return "dot_tick"
				if did_crit:
								return "crit"
				return "direct_hit"

func _spine_record(event_class, context):
				_spine_event_seq += 1
				var record = {"event_class": event_class, "seq": _spine_event_seq, "timestamp_ms": OS.get_ticks_msec()}
				record["did_kill"] = context.get("did_kill", false)
				for k in context:
								record[k] = context[k]
				_spine_last_events.append(record)
				if _spine_last_events.size() > 64:
								_spine_last_events.pop_front()
				return record

func apply_damage(damage_bundle, color = Color.white, attacker_stats = null, show_damage = false, is_dot_damage = false, skill_parent = null, can_block = true):

if is_dot_damage:
				accumulated_dot_damage += combined_effective_damage
				_spine_record("dot_tick", {"source": attacker_stats, "target": self, "is_dot": true})

if not is_dot_damage and damage_multiplier != 0:
				_spine_record(_spine_event_class(false, did_crit), {"source": attacker_stats, "target": self, "did_crit": did_crit, "is_dot": false, "skill_parent": skill_parent})
				on_take_damage(attacker_stats, damage_bundle, effective_damage, is_dot_damage, did_crit, skill_parent)

if attacker_stats != null and did_kill:

				attacker_stats.on_kill(self, is_dot_damage)
				_spine_record("kill", {"source": attacker_stats, "target": self, "is_dot": is_dot_damage, "did_kill": true})
